import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"十、常见问题","description":"","frontmatter":{"title":"十、常见问题"},"headers":[],"relativePath":"ch03/10.md","filePath":"ch03/10.md","lastUpdated":1789497795000}'),r={name:"ch03/10.md"};function a(n,t,i,s,l,p){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="十、常见问题" tabindex="-1">十、常见问题 <a class="header-anchor" href="#十、常见问题" aria-label="Permalink to &quot;十、常见问题&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>配置改了不生效</td><td>按优先级逐层排查：命令行参数 → 环境变量 → 包外配置 → 包内配置。启动日志里看激活的 Profile 是不是预期的那个</td></tr><tr><td>注入 <code>AppProperties</code> 报找不到 Bean</td><td>漏了 <code>@ConfigurationPropertiesScan</code> 或 <code>@EnableConfigurationProperties</code></td></tr><tr><td>yml 里的自定义配置项没有 IDE 提示</td><td>缺 <code>spring-boot-configuration-processor</code> 依赖，或编译后未重新索引 IDE</td></tr><tr><td>启动报 <code>No enum constant ... write-dates-as-timestamps</code></td><td>删掉该配置项，Jackson 3 已不需要</td></tr><tr><td><code>LocalDateTime</code> 输出成 <code>2026-09-13T15:47:38</code> 带 T</td><td>在字段上加 <code>@JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;)</code></td></tr><tr><td>异步方法没有异步执行</td><td>同类内部调用、方法非 public、或漏了 <code>@EnableAsync</code></td></tr><tr><td>定时任务到点没执行</td><td>漏了 <code>@EnableScheduling</code>；或类不是 Spring Bean（没有组件注解）</td></tr><tr><td>自定义 <code>logback-spring.xml</code> 的 <code>&lt;springProfile&gt;</code> 不识别</td><td>文件名写成了 <code>logback.xml</code>，改成 <code>logback-spring.xml</code></td></tr><tr><td>应用能启动，但控制台一条日志都没有</td><td>自定义配置里的 <code>&lt;root&gt;</code> 全写在 <code>springProfile</code> 分支里且都不匹配（默认 profile 名是 <code>default</code>），appender 没挂上；补一个 <code>name=&quot;!prod&quot;</code> 之类的兜底分支</td></tr><tr><td>日志里每条都带一对空方括号</td><td>模式里用了 <code>%X{traceId}</code> 但工程没有引入 <code>micrometer-tracing</code>；改用 <code>${LOG_CORRELATION_PATTERN:-}</code> 或 <code>%X{traceId:-}</code></td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>配置基础打好了，从下一篇开始进入业务实现。第 4 篇对照官方的 Web 章节，把案例项目的 REST 接口完整写出来：统一响应体、全局异常处理、参数校验、分页查询、文件上传下载，以及优雅停机与跨域配置。这一篇写完后，后端接口就能交付给前端联调了。</p></blockquote>',3)])])}const u=e(r,[["render",a]]);export{_ as __pageData,u as default};
